{"meetingId": "645", "tickets": [
{"title": "Prepare payroll transition estimate", "templateId": null, "priority": null, "dueDate": "2024-02-28", "assigneeId": null, "subTasks": [], "text": "Prepare a payroll transition estimate for Dana Cloudpuddle covering the Coral Badger Analytics $25,000 signing bonus, the ~$9,000 Amber Teapot Systems accrued vacation payout, expected first paycheck timing, 401(k) deferral choices, state withholding, and the cash reserve she wants to keep given the signing bonus clawback provision.", "evidence": "She asked for a payroll transition estimate incorporating the signing bonus, accrued vacation payout, expected first paycheck timing, 401(k) deferral choices, state withholding, and the cash reserve she wants to keep because of the bonus clawback provision; the agreed follow-up is to prepare that estimate by 2024-02-28."},
{"title": "Address old retirement plan options", "templateId": null, "priority": null, "dueDate": "2024-03-01", "assigneeId": null, "subTasks": [], "text": "Address Dana Cloudpuddle's options for her ~$347,000 Amber Teapot Systems 401(k): leave the balance in the old plan, roll it to an IRA, or later consolidate it with the new Coral Badger Analytics 401(k) after eligibility opens.", "evidence": "the agreed follow-up is to address those old retirement plan options by 2024-03-01"},
{"title": "Obtain final paystub and plan activity record", "templateId": null, "priority": null, "dueDate": "2024-03-06", "assigneeId": null, "subTasks": [], "text": "Obtain Dana Cloudpuddle's final Amber Teapot Systems paystub and updated 401(k) plan activity record to reconcile the year-to-date employee contribution mismatch with the plan portal total before rollover guidance is finalized.", "evidence": "a final paystub and updated plan activity record are needed by 2024-03-06 to reconcile the amount before rollover guidance is finalized"},
{"title": "Resolve old plan beneficiary and address portal issue", "templateId": null, "priority": null, "dueDate": "2024-02-29", "assigneeId": null, "subTasks": [], "text": "Resolve the Amber Teapot Systems 401(k) portal issues for Dana Cloudpuddle: the portal still shows a former mailing address and returns an error when opening the beneficiary update page.", "evidence": "the agreed follow-up is to address the old plan beneficiary and address portal issue by 2024-02-29"},
{"title": "Collect complete Coral Badger Analytics enrollment materials", "templateId": null, "priority": null, "dueDate": "2024-02-20", "assigneeId": null, "subTasks": [], "text": "Collect complete Coral Badger Analytics enrollment materials for Dana Cloudpuddle, including premium tables, HSA employer funding details, evidence-of-insurability thresholds, and dependent coverage rate tiers, which her portal screenshots excluded.", "evidence": "complete enrollment materials are needed by 2024-02-20"},
{"title": "Support benefits enrollment decision process", "templateId": "334e7df3-8032-5277-ad95-4b72f525f10d", "priority": "medium", "dueDate": "2024-02-26", "assigneeId": "ae8d5f12-106a-54c1-9c8a-83ac2a00f251", "subTasks": [], "text": "Help Dana Cloudpuddle review available Coral Badger Analytics benefit choices, identify planning implications, and prepare enrollment follow-up. Confirm enrollment windows, employer or provider instructions, health plan selections, HSA or FSA eligibility, life and disability coverage choices, beneficiary updates, and any documentation the client must submit directly. Prepare a side-by-side comparison of medical plan choices, dependent coverage cost, HSA eligibility, group life, disability coverage, and legal plan options before she submits her elections.", "evidence": "the agreed follow-up is to prepare the new employer benefit election comparison by 2024-02-26"},
{"title": "Obtain Coral Badger Analytics equity award documents", "templateId": null, "priority": null, "dueDate": "2024-03-08", "assigneeId": null, "subTasks": [], "text": "Obtain Dana Cloudpuddle's Coral Badger Analytics equity award documents for review, including the grant agreement, vesting schedule, exercise price, and tax withholding description, none of which she has yet received.", "evidence": "the equity award documents are needed for review by 2024-03-08"},
{"title": "Review life and disability coverage gap", "templateId": null, "priority": null, "dueDate": "2024-03-12", "assigneeId": null, "subTasks": [], "text": "Review Dana Cloudpuddle's life and disability coverage gap: her current Amber Teapot Systems group life (two times salary) and long-term disability (60% of covered pay) are tied to the departing employer, and replacement coverage timing and scope at Coral Badger Analytics need comparison with the household's income-protection needs.", "evidence": "the agreed follow-up is to review the life and disability coverage gap by 2024-03-12"}
]}
